do $$declare a uuid:='95000000-0000-0000-0000-000000000001';b uuid:='95000000-0000-0000-0000-000000000002';nid uuid;n bigint;p public.notification_preferences;begin
 insert into auth.users(id,email)values(a,'notify-a@x.iq'),(b,'notify-b@x.iq');
 insert into public.notifications(user_id,title,body,type,category,priority,dedupe_key)values(a,'تنبيه اختبار','خاص بالمستخدم الأول','warning','departure','high','test:a')returning id into nid;
 perform set_config('role','authenticated',false);perform set_config('request.jwt.claim.sub',b::text,false);select count(*)into n from public.notification_center(30,null);if n<>0 then raise exception'NOTIFICATION_ISOLATION_FAIL';end if;begin perform public.notification_mark_read(nid);raise exception'FOREIGN_NOTIFICATION_WRITE_ACCEPTED';exception when others then if sqlerrm='FOREIGN_NOTIFICATION_WRITE_ACCEPTED'then raise;end if;if sqlerrm not like'%NOTIFICATION_NOT_FOUND%'then raise;end if;end;
 perform set_config('request.jwt.claim.sub',a::text,false);select public.notification_unread_count()into n;if n<>1 then raise exception'NOTIFICATION_COUNT_FAIL';end if;perform public.notification_mark_read(nid);select public.notification_unread_count()into n;if n<>0 then raise exception'NOTIFICATION_READ_FAIL';end if;p:=public.notification_update_preferences(true,true,false,true,'22:00','06:00');if not p.critical_only or p.quiet_from<>'22:00'::time then raise exception'NOTIFICATION_PREFERENCES_FAIL';end if;perform public.notification_dismiss(nid);select count(*)into n from public.notification_center(30,null);if n<>0 then raise exception'NOTIFICATION_DISMISS_FAIL';end if;
 raise notice'✅ مركز الإشعارات: العزل/العداد/القراءة/الإخفاء/التفضيلات ناجحة';end$$;
